sys_script_client.script:
function onSubmit() {

    // --- ATENÇÃO: Verifique os nomes dos seus campos aqui ---
    var managerField = 'manager_base';
    var nameField = 'name';
    var cityField = 'city';
    var stateField = 'state';

    // 1. Rodar APENAS se um dos campos-chave for modificado ou for um novo registro
    if (g_form.isNewRecord() || g_form.isFieldModified(managerField) || g_form.isFieldModified(nameField) || g_form.isFieldModified(cityField) || g_form.isFieldModified(stateField)) {

        var ga = new GlideAjax('x_1836079_office.BaseUtils'); // <-- Use o seu API Name


        // // 2. Chamar a nossa ÚNICA "super-função"
        ga.addParam('sysparm_name', 'validateBaseSubmit'); 

        // // 3. Enviar TODOS os parâmetros de validação de uma vez
		ga.addParam('sysparm_manager_sysid', g_form.getValue(managerField));
		ga.addParam('sysparm_base_name', g_form.getValue(nameField)); // <-- ESTA É A LINHA QUE MUDAMOS
		ga.addParam('sysparm_city', g_form.getValue(cityField));
		ga.addParam('sysparm_state', g_form.getValue(stateField));
		ga.addParam('sysparm_current_base_sysid', g_form.getUniqueValue());

        // 4. Chamar o ÚNICO callback
        ga.getXML(validacaoCallback);

        return false; // Parar o envio (só uma vez!)
    }

    return true; // Se nada mudou, deixar salvar
}

// 5. Nosso ÚNICO callback
function validacaoCallback(response) {
    var answer = response.responseXML.documentElement.getAttribute("answer");

    // --- ATENÇÃO: Verifique os nomes dos seus campos aqui embaixo ---
    var managerField = 'manager_base';
    var nameField = 'name';
    var cityField = 'city';
    var stateField = 'state';

    // 6. Usar um 'switch' para tratar a resposta
    switch (answer) {
        case 'VALID':
            // Válido! Enviar o formulário (só uma vez!)
            g_form.submit(g_form.getActionName());
            break;

        case 'ERR_DUPE_MANAGER':
            // Erro da História 2
            g_form.addErrorMessage('Este gerente já está alocado em outra base. A submissão foi cancelada.');
            g_form.setValue(managerField, ''); // Limpar o campo
            break;

        case 'ERR_DUPE_NAME':
            // Erro da História 4a
            g_form.addErrorMessage('Já existe uma base com este Nome. A submissão foi cancelada.');
            g_form.setValue(nameField, ''); // Limpar o campo
            break;

        case 'ERR_DUPE_LOCATION':
            // Erro da História 4b
            g_form.addErrorMessage('Já existe uma base com esta combinação de Cidade e Estado. A submissão foi cancelada.');
            g_form.setValue(cityField, ''); // Limpar os campos
            g_form.setValue(stateField, '');
            break;

        default:
            // Erro inesperado
            g_form.addErrorMessage('Ocorreu um erro inesperado na validação: ' + answer);
    }
}
